const caseDialog=document.querySelector('#caseDialog');
const caseContent=document.querySelector('#caseContent');
let caseRevealObserver;
function openCaseStudy(study){
  const keys=Object.keys(studies);
  const currentKey=keys.find(key=>studies[key]===study);
  const nextStudy=studies[keys[(keys.indexOf(currentKey)+1)%keys.length]];
  const sections=study.sections.filter(section=>section&&section.body).map((section,index)=>`<section class="case-section case-reveal case-section-${index+1}"><div class="case-section-heading"><span class="case-section-label">${section.label}</span><h3>${section.title}</h3></div><div class="case-section-copy"><p>${section.body}</p>${section.points?.length?`<ul class="case-points">${section.points.map((point,pointIndex)=>`<li><span>0${pointIndex+1}</span>${point}</li>`).join('')}</ul>`:''}</div></section>`).join('');
  const simpleStory=study.storyline.map(([label,copy],index)=>`<article><span>0${index+1}</span><small>${label}</small><p>${copy}</p></article>`).join('');
  const motionBlocks=Array.from({length:6},(_,index)=>`<i style="--motion-index:${index}"></i>`).join('');
  caseContent.innerHTML=`<article class="case-study case-${currentKey}" style="--case-accent:${study.accent};--case-contrast:${study.contrast}"><div class="case-progress" aria-hidden="true"><i></i></div><header class="case-opening"><div class="case-opening-top"><span>CASE STUDY / ${study.index}</span><span>KAREM EHAB · UI/UX</span></div><div class="case-lockup"><div><span class="case-tag">${study.category}</span><h2 class="case-title">${study.title}</h2></div><p class="case-intro">${study.intro}</p></div></header><figure class="case-visual case-reveal"><img src="${study.image}" alt="${study.alt}" width="1536" height="1024" decoding="async"><figcaption><span>Selected interface direction</span><b>${study.platform}</b></figcaption></figure><dl class="case-meta case-reveal"><div><dt>Role</dt><dd>${study.role}</dd></div><div><dt>Platform</dt><dd>${study.platform}</dd></div><div><dt>Scope</dt><dd>${study.scope}</dd></div></dl><section class="case-explainer case-reveal"><header><span>THE SIMPLE STORY</span><h3>What changed—and why it matters.</h3></header><div class="case-explainer-grid">${simpleStory}</div></section><div class="case-story">${sections}</div><section class="case-showcase"><header class="case-reveal"><span>DESIGN IN ACTION</span><h3>See the idea,<br>not just the words.</h3></header><div class="case-gallery case-reveal"><figure><img src="${study.image}" alt="" width="1536" height="1024" loading="lazy" decoding="async"><figcaption>${study.cropLabels[0]}</figcaption></figure><figure><img src="${study.image}" alt="" width="1536" height="1024" loading="lazy" decoding="async"><figcaption>${study.cropLabels[1]}</figcaption></figure></div><div class="case-motion-preview case-reveal"><div class="case-motion-copy"><span>MOTION PREVIEW</span><h3>${study.motionTitle}</h3><p>${study.motionBody}</p></div><div class="case-motion-stage motion-${currentKey}" role="img" aria-label="Looping interface motion preview"><div class="case-motion-device"><b></b>${motionBlocks}</div><span class="motion-orbit" aria-hidden="true"></span></div></div></section><footer class="case-next case-reveal"><div><span>Next case</span><h3>${nextStudy.title}</h3></div><button type="button" class="case-next-button" data-next-case="${keys[(keys.indexOf(currentKey)+1)%keys.length]}">View project</button><p>${study.next}</p></footer></article>`;
  if(!caseDialog.open)caseDialog.showModal();
  caseDialog.scrollTop=0;
  document.body.classList.add('case-open');
  requestAnimationFrame(()=>caseContent.querySelector('.case-study').classList.add('case-entered'));
  caseContent.querySelector('[data-next-case]').addEventListener('click',event=>openCaseStudy(studies[event.currentTarget.dataset.nextCase]));
  caseRevealObserver?.disconnect();
  caseRevealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>entry.target.classList.toggle('is-in-view',entry.isIntersecting)),{root:caseDialog,rootMargin:'-8% 0px -12%',threshold:.12});
  caseContent.querySelectorAll('.case-reveal').forEach(node=>caseRevealObserver.observe(node));
}
document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>openCaseStudy(studies[button.dataset.project])));
caseDialog.addEventListener('scroll',()=>{const progress=caseContent.querySelector('.case-progress i');if(!progress)return;const max=caseDialog.scrollHeight-caseDialog.clientHeight;progress.style.transform=`scaleX(${max?Math.min(1,caseDialog.scrollTop/max):0})`},{passive:true});
caseDialog.addEventListener('close',()=>{document.body.classList.remove('case-open');caseRevealObserver?.disconnect()});
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()})});
document.querySelectorAll('[data-color]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-color]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});const c=document.querySelector('#playCanvas');if(!c)return;c.style.setProperty('--accent',b.dataset.color);c.style.setProperty('--play-ink',b.dataset.color==='#2b39ef'?'white':'#191a1c')}));let remix=0;const shuffle=document.querySelector('#shuffle');if(shuffle)shuffle.addEventListener('click',()=>{remix++;const card=document.querySelector('.play-card');card.style.transform=`rotate(${[-7,0,6][remix%3]}deg)`;card.querySelector('h3').innerHTML=['Make<br>your mark.','Stay<br>curious.','Find<br>your flow.'][remix%3];card.querySelector('.play-shapes').style.flexDirection=remix%2?'row-reverse':'row'});
let toastTimer;function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3200)}
document.querySelector('#hello')?.addEventListener('click',e=>{toast('A little joy goes a long way.');if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const r=e.currentTarget.getBoundingClientRect();for(let i=0;i<18;i++){const x=document.createElement('span');x.className='spark';x.textContent=['◎','◈','○'][i%3];x.style.left=r.left+r.width/2+'px';x.style.top=r.top+'px';x.style.color=['#2b39ef','#809b1a','#ff8866'][i%3];x.style.setProperty('--dx',(Math.random()-.5)*350+'px');x.style.setProperty('--dy',-60-Math.random()*220+'px');document.body.append(x);setTimeout(()=>x.remove(),1300)}});
document.querySelector('#contactButton').addEventListener('click',()=>{document.querySelector('#contact').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});document.querySelector('#briefTitle').focus({preventScroll:true})});document.querySelector('#briefForm').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);const text=window.portfolioLocale==='ar'?`فكرة مشروع لكريم إيهاب\n\nالاسم: ${f.get('name')}\nالبريد الإلكتروني: ${f.get('email')}\n\nالمشروع:\n${f.get('project')}\n`:`PROJECT BRIEF FOR KAREM EHAB\n\nName: ${f.get('name')}\nEmail: ${f.get('email')}\n\nProject:\n${f.get('project')}\n`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='project-brief-for-karem.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your brief is ready to share.');});document.querySelector('#year').textContent=new Date().getFullYear();
